import app from 'flarum/common/app';
/** "/series/12-the-long-road", or "/series/12" for a title with no Latin letters. */
export const seriesUrl = series => app.route('anthology.series', {
  id: series.id + (series.slug ? '-' + series.slug : '')
});
export const chapterUrl = chapter => app.route('discussion', {
  id: chapter.id + (chapter.slug ? '-' + chapter.slug : '')
});

/** The id at the front of an "id-slug" route parameter. */
export const routeId = param => parseInt(String(param || ''), 10) || 0;
flarum.reg.add('ernestdefoe-anthology', 'common/urls', { seriesUrl: seriesUrl,chapterUrl: chapterUrl,routeId: routeId, });