import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import LinkButton from 'flarum/common/components/LinkButton';
import Icon from 'flarum/common/components/Icon';
import extractText from 'flarum/common/utils/extractText';
import { chapterUrl, seriesUrl } from '../../common/urls';
import { t } from '../util';
/** Under a chapter's title: the series, "Chapter 3 of 15", previous, all chapters, next. */
export class ChapterBar extends Component {
  view() {
    const series = this.attrs.series;
    const step = (to, icon, label) => to ? m(Link, {
      className: "AnthologyBar-step",
      href: chapterUrl(to),
      title: to.title,
      "aria-label": extractText(t(label)) + ': ' + to.title
    }, m(Icon, {
      name: icon
    })) : m("span", {
      className: "AnthologyBar-step disabled",
      "aria-hidden": "true"
    }, m(Icon, {
      name: icon
    }));
    return m("div", {
      className: "AnthologyBar"
    }, m(Link, {
      className: "AnthologyBar-series",
      href: seriesUrl(series),
      title: extractText(t('chapter_bar.contents'))
    }, series.coverUrl ? m("img", {
      className: "AnthologyBar-cover",
      src: series.coverUrl,
      alt: "",
      loading: "lazy"
    }) : m(Icon, {
      name: "fas fa-book-bookmark"
    }), m("span", {
      className: "AnthologyBar-text"
    }, m("span", {
      className: "AnthologyBar-label"
    }, t('chapter_bar.label', {
      number: series.number,
      count: series.count
    })), m("span", {
      className: "AnthologyBar-title"
    }, series.title))), m("span", {
      className: "AnthologyBar-nav"
    }, step(series.prev, 'fas fa-chevron-left', 'chapter_bar.previous'), m(Link, {
      className: "AnthologyBar-step",
      href: seriesUrl(series),
      title: extractText(t('chapter_bar.contents')),
      "aria-label": extractText(t('chapter_bar.contents'))
    }, m(Icon, {
      name: "fas fa-list-ol"
    })), step(series.next, 'fas fa-chevron-right', 'chapter_bar.next')));
  }
}

/** After the chapter's text: previous, all chapters and the next chapter by name. */
export class NextChapter extends Component {
  view() {
    const series = this.attrs.series;
    return m("nav", {
      className: "AnthologyNext",
      "aria-label": series.title
    }, m("div", {
      className: "AnthologyNext-meta"
    }, t('chapter_bar.label', {
      number: series.number,
      count: series.count
    }), " \xB7 ", m(Link, {
      href: seriesUrl(series)
    }, series.title)), m("div", {
      className: "AnthologyNext-actions"
    }, series.prev ? m(LinkButton, {
      className: "Button",
      icon: "fas fa-chevron-left",
      href: chapterUrl(series.prev),
      title: series.prev.title
    }, t('chapter_bar.previous')) : null, m(LinkButton, {
      className: "Button",
      icon: "fas fa-list-ol",
      href: seriesUrl(series)
    }, t('chapter_bar.contents')), series.next ? m(LinkButton, {
      className: "Button Button--primary AnthologyNext-next",
      href: chapterUrl(series.next),
      title: series.next.title
    }, m("span", {
      className: "AnthologyNext-nextLabel"
    }, t('chapter_bar.next'), ":"), ' ', m("span", {
      className: "AnthologyNext-nextTitle"
    }, series.next.title), " ", m(Icon, {
      name: "fas fa-chevron-right"
    })) : null));
  }
}
flarum.reg.add('ernestdefoe-anthology', 'forum/components/ChapterBar', { ChapterBar: ChapterBar,NextChapter: NextChapter, });